#!/usr/bin/env node
// extract.js - Extract memory values from an ELF binary.
// Usage: node extract.js <binary>  -> JSON { "<addr>": <value>, ... }
const fs = require('fs');

function extract(path) {
  const buf = fs.readFileSync(path);
  if (buf.length < 64 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    console.error('Not an ELF file: ' + path);
    process.exit(1);
  }
  const out = {};
  const is64 = buf[4] === 2;
  if (is64) {
    const e_phoff = Number(buf.readBigUInt64LE(32));
    const e_phentsize = buf.readUInt16LE(54);
    const e_phnum = buf.readUInt16LE(56);
    for (let i = 0; i < e_phnum; i++) {
      const ph = e_phoff + i * e_phentsize;
      const p_type = buf.readUInt32LE(ph);
      if (p_type !== 1) continue; // PT_LOAD
      const p_offset = Number(buf.readBigUInt64LE(ph + 8));
      const p_vaddr = Number(buf.readBigUInt64LE(ph + 16));
      const p_filesz = Number(buf.readBigUInt64LE(ph + 32));
      const p_memsz = Number(buf.readBigUInt64LE(ph + 24));
      addSegment(buf, out, p_offset, p_vaddr, p_filesz, p_memsz);
    }
  } else {
    const e_phoff = buf.readUInt32LE(28);
    const e_phentsize = buf.readUInt16LE(42);
    const e_phnum = buf.readUInt16LE(44);
    for (let i = 0; i < e_phnum; i++) {
      const ph = e_phoff + i * e_phentsize;
      const p_type = buf.readUInt32LE(ph);
      if (p_type !== 1) continue;
      const p_offset = buf.readUInt32LE(ph + 4);
      const p_vaddr = buf.readUInt32LE(ph + 8);
      const p_filesz = buf.readUInt32LE(ph + 16);
      const p_memsz = buf.readUInt32LE(ph + 20);
      addSegment(buf, out, p_offset, p_vaddr, p_filesz, p_memsz);
    }
  }
  return out;
}

function addSegment(buf, out, offset, vaddr, filesz, memsz) {
  if (filesz > memsz) filesz = memsz;
  // byte accessor relative to segment start
  const getByte = (rel) => (rel < filesz ? buf[offset + rel] : 0);
  // iterate 4-byte aligned words covering [vaddr, vaddr+memsz)
  for (let rel = 0; rel + 4 <= memsz; rel += 4) {
    const addr = vaddr + rel;
    const v = (getByte(rel) | (getByte(rel + 1) << 8) | (getByte(rel + 2) << 16) | (getByte(rel + 3) << 24)) >>> 0;
    out[addr] = v; // placeholder replaced below
  }
}

const target = process.argv[2];
const result = extract(target);
process.stdout.write(JSON.stringify(result));
EOF

